    [Theory]
    [MemberData(nameof(PythonFileControls))]
    public async Task EverySmallWindowMatchesPython(string name, int encoding,
        int errors, int newline, string hex, string? expected, string? failure)
    {
        _ = name;
        foreach (var window in new[] { 1, 2, 3, 4, 5, 7 })
        foreach (var asynchronous in new[] { false, true })
        {
            var host = new MockLythonHost();
            host.SeedBytes("/input", Convert.FromHexString(hex));
            var context = new LythonRuntime.ExecutionContext(host, new LythonRunOptions { MaxExecutionMemoryBytes = 100000 });
            var state = new LythonRuntime.ExecutionContext.ChunkedTextFileReadState("/input", context,
                (LythonRuntime.TextEncodingMode)encoding, (LythonRuntime.TextErrorMode)errors, (LythonRuntime.TextNewlineMode)newline, window);
            try
            {
                if (failure is not null)
                {
                    var error = asynchronous
                        ? await Assert.ThrowsAsync<LythonRuntimeException>(async () => { await state.PrimeAsync(); _ = await state.ReadAsync(-1); })
                        : Assert.Throws<LythonRuntimeException>(() => { state.Prime(); _ = state.Read(-1); });
                    Assert.Equal(failure, error.ExceptionType);
                }
                else
                {
                    if (asynchronous) await state.PrimeAsync(); else state.Prime();
                    var value = asynchronous ? await state.ReadAsync(-1) : state.Read(-1);
                    Assert.Equal(expected, value.AsString());
                }
            }
            finally { state.Release(); }
            Assert.Equal(0, context.MemoryGovernor.CurrentReservedBytes);
        }
    }
